-- =============================================================
-- 테스트 시드 데이터
-- k6/config.js 의 SEED UUID와 일치
-- =============================================================

-- -------------------------------------------------------------
-- Users (5명)
-- UUID: 00000000-0000-0000-0000-00000000000{1~5}
-- -------------------------------------------------------------

-- 잔액: 각 1,000,000원 (결제 테스트 충분히 가능)

-- -------------------------------------------------------------
-- Concert
-- UUID: 10000000-0000-0000-0000-000000000001
-- -------------------------------------------------------------

-- -------------------------------------------------------------
-- Concert Date
-- UUID: 20000000-0000-0000-0000-000000000001
-- -------------------------------------------------------------

-- -------------------------------------------------------------
-- Seats (50석)
-- hotSeatId (동시성 테스트용): 30000000-0000-0000-0000-000000000001 → seat_number 1
-- 나머지 49석: 30000000-0000-0000-0000-000000000002 ~ 050
-- 가격: 99,000원
-- -------------------------------------------------------------
